// A scripted greenfield run on the real template: honest TDD through G1/G2, route index regenerated by the
// harness, and the standards checks at 100% from inside the run.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { renderIndex } from '../plugins/hooks/route-index/index.js';
import { REPO_ROOT, call, greenGate, makeRepo, readEvents, removeDir, scriptedRun } from './helpers.js';

const good = (rel: string) => readFileSync(join(REPO_ROOT, 'test/fixtures/good-api', rel), 'utf8');

let repo: string;
beforeAll(() => {
  repo = makeRepo('greenfield');
});
afterAll(() => removeDir(repo));

describe('scripted greenfield run', () => {
  it('reaches 100% standards through the gates', async () => {
    const summary = await scriptedRun(
      repo,
      [
        { toolCalls: [call('write_file', { path: 'test/routes/users.test.ts', content: good('test/routes/users.test.ts') }), call('write_file', { path: 'test/schemas/user.test.ts', content: good('test/schemas/user.test.ts') })] },
        { toolCalls: [call('run_tests')] },
        { toolCalls: [call('write_file', { path: 'src/schemas/user.ts', content: good('src/schemas/user.ts') })] },
        { toolCalls: [call('write_file', { path: 'src/routes/users.ts', content: good('src/routes/users.ts') })] },
        { toolCalls: [call('run_tests')] },
        { toolCalls: [call('run_checks')] },
        { toolCalls: [call('finish')] },
      ],
      { finishGate: greenGate },
    );
    const events = readEvents(repo, summary.runId);
    const tools = events.filter((e) => e.type === 'tool');
    const tests = tools.filter((e) => e.tool === 'run_tests').map((e) => String(e.summary));
    expect(tests[0]).toMatch(/FAIL 2/);
    expect(tests[1]).toMatch(/^PASS \d+ \/ FAIL 0 — all green/);
    expect(events.filter((e) => e.hook === 'observed-red').map((e) => e.decision)).toEqual(['record', 'record']);
    expect(events.find((e) => e.hook === 'route-index')).toMatchObject({ decision: 'record', exit: 1 });
    const checks = String(tools.find((e) => e.tool === 'run_checks')?.summary);
    expect(checks).toMatch(/verdict\s+100%/);
    const apiRoot = join(repo, summary.worktree, 'generated', 'users-api');
    expect(readFileSync(join(apiRoot, 'src/routes/index.ts'), 'utf8')).toBe(renderIndex(['users']));
    expect(readFileSync(join(repo, 'reports', summary.runId, 'standards.txt'), 'utf8')).toMatch(/verdict\s+100%/);
    expect(summary.status).toBe('green');
  });

  it('blocks model writes to the generated route index', async () => {
    const summary = await scriptedRun(repo, [{ toolCalls: [call('write_file', { path: 'src/routes/index.ts', content: 'export const routes = [];\n' })] }], { maxTurns: 1 });
    expect(readEvents(repo, summary.runId).find((e) => e.hook === 'path-guard')).toMatchObject({ decision: 'block' });
  });
});
